---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Event calendar: A week view where the agent finds a free slot for you.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change event-calendar.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './event-calendar.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'wide', className]} data-c="event-calendar" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="ecx panel">
  <div class="ecx-h"><b>Oct 19 – 23, 2026</b><span class="ecx-sp"></span><span class="ecx-msg muted"></span><button class="pill soft sm ecx-ask"><svg class="i xs"><use href="#i-spark"/></svg>Find 45 min for a design review</button></div>
  <div class="ecx-days" role="group" aria-label="Day"></div>
  <div class="ecx-sc"><div class="ecx-grid"><div class="ecx-tm"></div></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './event-calendar.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Event calendar ---------- */
.ecx{overflow:hidden;position:relative;container:ecx/inline-size}
/* the Ask pill crossfades its words but stays a flex row, so the spark keeps its gap */
.ecx-ask.sw{display:inline-flex}
/* while the agent checks, its words carry the loaders' highlight sweep in the pill's own colour */
.ecx-ask .shim{color:inherit;-webkit-text-fill-color:transparent;background-image:linear-gradient(90deg,currentColor 0%,currentColor 38%,var(--dm-faint) 50%,currentColor 62%,currentColor 100%)}
/* the Ask pill is an accent tint, like a picked preset in Date range picker */
.pill.soft.ecx-ask{background:var(--dm-sel);color:var(--dm-accent-fg,var(--dm-accent));box-shadow:none}
@media (hover:hover) and (pointer:fine){.pill.soft.ecx-ask:hover{background:color-mix(in srgb,var(--dm-accent) 14%,transparent)}}
.ecx-h{display:flex;align-items:center;gap:var(--dm-s-2);padding:10px var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13.5px;flex-wrap:wrap}
.ecx-h b{font-weight:500}
.ecx-sp{flex:1}
.ecx-sc{overflow-x:auto}
/* --dm-ph is the height of an hour: every event, the grid lines and the time column are laid out in hours of it */
.ecx-grid{display:grid;grid-template-columns:44px repeat(var(--dm-days,5),minmax(76px,1fr));min-width:424px;position:relative;--dm-ph:44px}
.ecx-tm{grid-row:1/3;display:flex;flex-direction:column;padding-top:var(--dm-s-8)}
.ecx-tm span{height:var(--dm-ph);font-size:10.5px;color:var(--dm-muted);text-align:right;padding-right:var(--dm-s-2);transform:translateY(-6px)}
.ecx-tm i{font-style:normal}
/* the time column reads in hours (9am), and in half hours (9:00, 9:30) where one row is 30 minutes */
.ecx-tm .hf,.ecx-tm .n{display:none}
.ecx-day{border-left:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ecx-dh{height:32px;display:flex;align-items:center;justify-content:center;gap:5px;font-size:12px;color:var(--dm-fg2);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.ecx-dh b{font-weight:500;color:var(--dm-fg)}
.ecx-dh.t b{width:22px;height:22px;border-radius:50%;background:var(--dm-accent);color:var(--dm-on-accent);display:grid;place-items:center;font-size:11.5px}
.ecx-col{position:relative;height:calc(var(--dm-ph) * 8);background-image:linear-gradient(color-mix(in srgb,var(--dm-line) 50%,transparent) 1px,transparent 1px);background-size:100% var(--dm-ph)}
.ecx-e{position:absolute;left:3px;right:3px;border-radius:var(--dm-r-sm);padding:var(--dm-s-1) 7px;font-size:11.5px;line-height:1.3;text-align:left;overflow:hidden;transition:transform .25s var(--dm-ease),box-shadow .25s}
@media (hover:hover) and (pointer:fine){.ecx-e:hover{transform:translateY(-1px);box-shadow:var(--dm-shadow)}}
/* every event keeps its pastel pair at full strength, and its hover is a deeper fill in its own colour; an event whose card is
   open is a step deeper, with a faint ring in its colour. No lift, no drop shadow, no grey ring (owner, 20 Nov: "the selected
   state hover shadow is so bad"). (The Sales CRM's calendar has its own, the same) */
.ecx:not(.crm-ecx) .ecx-e{transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.ecx:not(.crm-ecx) .ecx-e:hover{transform:none}}
@media (hover:hover) and (pointer:fine){.ecx:not(.crm-ecx) .ecx-e:not(.sug,.drag):hover{box-shadow:none}}
@media (hover:hover) and (pointer:fine){.ecx:not(.crm-ecx) .ecx-e:not(.sug,.drag):hover{box-shadow:inset 0 0 0 100vmax color-mix(in srgb,currentColor 7%,transparent)}}
.ecx:not(.crm-ecx) .ecx-e.on:not(.sug,.drag){box-shadow:inset 0 0 0 100vmax color-mix(in srgb,currentColor 10%,transparent),inset 0 0 0 1px color-mix(in srgb,currentColor 35%,transparent)}
/* events sit in the scrolling grid, which would cut an outside ring: theirs is drawn inside */
.ecx-e:focus-visible{outline-offset:-2px}
.ecx-e{cursor:grab;touch-action:none}
.ecx-e.drag{transition:none;z-index:6;box-shadow:var(--dm-shadow-pop);cursor:grabbing}
.ecx-col{cursor:copy}
.ecx-ghost{position:absolute;left:3px;right:3px;height:calc(var(--dm-ph) - 3px);border-radius:var(--dm-r-sm);border:1.5px dashed color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 45%,transparent);background:color-mix(in srgb,var(--dm-accent) 5%,transparent);color:var(--dm-accent-fg,var(--dm-accent));font-size:11px;font-weight:500;padding:var(--dm-s-1) 7px;pointer-events:none}
.ecx-now{position:absolute;left:0;right:0;height:2px;margin-top:-1px;background:var(--dm-bad-mark);z-index:3}
.ecx-now::before{content:"";position:absolute;left:-4px;top:-3px;width:8px;height:8px;border-radius:50%;background:var(--dm-bad-mark)}
.ecx-msg{font-size:12.5px;margin-right:var(--dm-s-2)}
.ecx-pop{position:absolute;z-index:20;width:248px;padding:var(--dm-s-3);background:var(--dm-raised);border-radius:calc(14px * var(--dm-rk-l,var(--dm-rk)));box-shadow:var(--dm-shadow-pop);opacity:0;visibility:hidden;transform:translateY(6px);filter:blur(3px);pointer-events:none;transition:opacity .2s var(--dm-ease),transform .35s var(--dm-ease),filter .2s,visibility 0s .2s}
.ecx-pop.open{opacity:1;visibility:visible;transform:none;filter:none;pointer-events:auto;transition-property:opacity,transform,filter}
.ecx-ph{display:flex;align-items:center;gap:var(--dm-s-2);font-size:13.5px}
.ecx-ph>i{width:10px;height:10px;border-radius:var(--dm-r-tiny,3px);flex:none}
.ecx-ph b{font-weight:500;flex:1;min-width:0}
.ecx-ph .ib{width:24px;height:24px;margin:-4px -4px -4px auto}
/* a new event's title is a field like any other: white, the dimmed field edge, one step stronger while you type */
.ecx-ti{flex:1;min-width:0;height:32px;padding:0 var(--dm-s-3);border:0;outline:0;border-radius:var(--dm-r-field);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line) 50%,transparent);font:inherit;font-weight:500;color:var(--dm-fg);transition:box-shadow var(--dm-t-fast)}
@supports (corner-shape:squircle){.ecx-ti{corner-shape:squircle;border-radius:var(--dm-r-field-sq)}}
.ecx-ti::placeholder{color:var(--dm-muted)}
.ecx-ti:focus{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-field-line-strong) 50%,transparent)}
.ecx-pt{font-size:12.5px;color:var(--dm-fg2);margin:var(--dm-s-1) 0 0 18px}
.ecx-pw{display:flex;align-items:center;margin:10px 0 0 18px}
.ecx-pw .av{width:22px;height:22px;font-size:9px;margin-right:-4px;box-shadow:0 0 0 2px var(--dm-raised)}
.ecx-pw .muted{margin-left:10px;font-size:12px}
/* the library's event card (the Sales CRM's, built on it, keeps its own): 16px in from its edges, the close button's glyph
   16px in on the title's line, and the people side by side, never stacked over each other. Everything under the title (the
   time, the people, the notes and the buttons) starts at the card's left content edge, where the colour dot sits, so both
   sides have the same room (owner, 20 Nov) */
.ecx-pop:not(.crm-cpop){padding:var(--dm-s-4)}
.ecx-pop:not(.crm-cpop) :is(.ecx-pt,.ecx-pw,.ecx-note,.ecx-pa){margin-left:0}
.ecx-pop:not(.crm-cpop) .ecx-ph .ib{margin:-4px -6px -4px auto}
.ecx-pop:not(.crm-cpop) .ecx-pw{gap:var(--dm-s-1)}
.ecx-pop:not(.crm-cpop) .ecx-pw .av{margin-right:0;box-shadow:none}
.ecx-pop:not(.crm-cpop) .ecx-pw .muted{margin-left:6px}
.ecx-note{display:flex;gap:6px;align-items:flex-start;margin:10px 0 0 18px;font-size:12px;line-height:1.45;color:var(--dm-fg2)}
.ecx-note .i{color:var(--dm-accent-fg,var(--dm-accent));margin-top:2px}
.ecx-pa{display:flex;justify-content:flex-end;gap:6px;margin:var(--dm-s-3) 0 0 18px}
/* the card's buttons share the width of its text column, the main one last (owner, 10 Nov) */
.ecx-pa>.pill{flex:1 1 0;justify-content:center}
.ecx-prep.done{color:var(--dm-fg2)}
.ecx-prep.done>.i{color:var(--dm-ok-mark)}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.ecx:not(.crm-ecx) :is(.ib,.pill,.ecx-days button):active,:root[data-style="clean"] .ecx:not(.crm-ecx) .ib:active,:root [data-style="clean"] .ecx:not(.crm-ecx) .ib:active,:root [data-style="clean"].ecx:not(.crm-ecx) .ib:active{transform:none}
.ecx-e b{display:block;font-weight:500;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ecx-e span{font-size:10.5px}
.ecx-e.sug{background:var(--dm-surface)!important;color:var(--dm-accent-fg,var(--dm-accent))!important;box-shadow:inset 0 0 0 1.5px var(--dm-accent-mark,var(--dm-accent));animation:ecs .6s var(--dm-ease) both}
.ecx-e.sug.alt{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-accent-mark,var(--dm-accent)) 40%,transparent)}
@keyframes ecs{from{opacity:0;transform:scale(.92);filter:blur(3px)}}
.ecx-sg{display:flex;gap:var(--dm-s-1);margin-top:var(--dm-s-1)}
.ecx-sg button{font-size:10.5px;padding:2px 6px;border-radius:var(--dm-r-tiny,5px);background:var(--dm-accent);color:var(--dm-on-accent)}
.ecx-sg button.n{background:transparent;color:var(--dm-accent-fg,var(--dm-accent))}
.ecx-scan{position:absolute;left:44px;right:0;height:2px;background:linear-gradient(90deg,transparent,var(--dm-accent),transparent);top:32px;opacity:0;pointer-events:none}
.ecx-scan.go{animation:ecsc 1.2s var(--dm-ease-io) both}
@keyframes ecsc{0%{opacity:0;top:32px}20%{opacity:1}100%{opacity:0;top:384px}}
/* a narrow calendar, on a phone or in a narrow card: one day at a time, picked from a row of days, so every event has room
   for its whole title and time. Each row of the grid is half an hour (owner, 4 Nov): an hour is two rows, so an event from
   9 to 10 is two rows tall, and the time column reads 9:00, 9:30, 10:00 */
.ecx-days{display:none}
@container ecx (max-width:519px){
  .ecx-days{display:flex;gap:var(--dm-s-1);padding:var(--dm-s-2) var(--dm-s-3);border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
  .ecx-days button{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;gap:2px;padding:var(--dm-s-1) 0;border-radius:var(--dm-r-sm);font-size:11.5px;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
  @media (hover:hover) and (pointer:fine){.ecx-days button:hover{background:var(--dm-row);color:var(--dm-fg)}}
  .ecx-days button[aria-pressed="true"]{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
  .ecx-days b{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;font-size:13px;font-weight:500;color:var(--dm-fg)}
  .ecx-days .t b{background:var(--dm-accent);color:var(--dm-on-accent)}
  .ecx-sc{overflow:visible}
  .ecx-grid{grid-template-columns:44px minmax(0,1fr);min-width:0;padding-top:var(--dm-s-2);--dm-ph:56px}
  .ecx-col{background-size:100% calc(var(--dm-ph) / 2)}
  .ecx-tm span{height:calc(var(--dm-ph) / 2)}
  .ecx-tm .hf,.ecx-tm .n{display:block}
  .ecx-tm .w{display:none}
  .ecx-day:not(.on){display:none}
  .ecx-dh{display:none}
  .ecx-tm{grid-row:auto;padding-top:0}
  .ecx-scan{top:8px}
  .ecx-scan.go{animation-name:ecscn}
  .ecx-pop{max-width:calc(100% - 16px)}
}
/* a calendar too narrow for the week and the agent's button side by side stacks its head: the week on its line, the button under
   it on the same left edge */
@container ecx (max-width:360px){
  .ecx:not(.crm-ecx)>.ecx-h{flex-direction:column;align-items:flex-start}
  .ecx:not(.crm-ecx)>.ecx-h>:is(.ecx-sp,.ecx-msg:empty){display:none}
}
@keyframes ecscn{0%{opacity:0;top:8px}20%{opacity:1}100%{opacity:0;top:calc(var(--dm-ph) * 8 + 8px)}}
/* Clean (owner, 17 and 18 Nov): an off-white head strip with the week and the agent's ask, which sits 16px from the card's edges
   and the strip's hairline (owner, 23 Nov); the days 16px in from the card's sides, running on to its foot as Soft's do. Events keep their colours and are
   ordinary rounded rectangles, never pills. The event card takes the card's 22px corners and is 16px in on every side, as in
   Soft (owner, 20 Nov). Book is the ink button. (The Sales CRM's calendar and event card are built on these classes and keep
   their own layout) */
:root[data-style="clean"] .ecx.panel:not(.crm-ecx),:root [data-style="clean"] .ecx.panel:not(.crm-ecx),:root [data-style="clean"].ecx.panel:not(.crm-ecx){padding:0 16px}
/* (the Sales CRM's calendar keeps the padding this card's earlier Clean rule gave it) */
:root[data-style="clean"] .ecx.panel.crm-ecx,:root [data-style="clean"] .ecx.panel.crm-ecx,:root [data-style="clean"].ecx.panel.crm-ecx{padding:10px 17px 0 10px}
:root[data-style="clean"] .ecx:not(.crm-ecx)>.ecx-h,:root [data-style="clean"] .ecx:not(.crm-ecx)>.ecx-h,:root [data-style="clean"].ecx:not(.crm-ecx)>.ecx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:0 -16px;padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .ecx-e,:root [data-style="clean"] .ecx-e,:root [data-style="clean"].ecx-e,:root[data-style="clean"] .ecx-ghost,:root [data-style="clean"] .ecx-ghost,:root [data-style="clean"].ecx-ghost{border-radius:var(--dm-r-sm)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-sg button{border-radius:var(--dm-r-xs)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button.y,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button.y,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-sg button.y{background:var(--dm-btn-2);color:var(--dm-on-btn)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button.n,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-sg button.n,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-sg button.n{color:var(--dm-fg)}
:root[data-style="clean"] .ecx-pop:not(.crm-cpop),:root [data-style="clean"] .ecx-pop:not(.crm-cpop),:root [data-style="clean"].ecx-pop:not(.crm-cpop){border-radius:var(--dm-r-card)}
:root[data-style="clean"] .ecx-pop:not(.crm-cpop) .ecx-note .i,:root [data-style="clean"] .ecx-pop:not(.crm-cpop) .ecx-note .i,:root [data-style="clean"].ecx-pop:not(.crm-cpop) .ecx-note .i{color:var(--dm-fg2)}
@container ecx (max-width:519px){:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-days,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-days,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-days{padding:8px 0}}
/* Clean (owner, 21 Nov: "same with calendar components especially the popup"). The events keep their saturated colours (owner,
   20 Nov: no washed-out calendars) with Clean's touches: 10px corners, a 3px rail down their left in their own colour over
   their tint, a hover that deepens their fill, eased, and an open event ringed in a neutral grey. The now line is a crisp 1px
   red line. The event card is Clean's popover (22px corners, its shadow, scaling and fading from the event it opens beside):
   a head strip with the event's colour, its title and a ghost ×; the time and the people (side by side, as in Soft, and how
   many) in its body; and Prep notes (a flat secondary) and Join (the ink primary), the same height, in its foot strip */
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-e,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-e,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-e{border-radius:10px;padding:4px 7px 4px 10px;transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-e:not(.sug),:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-e:not(.sug),:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-e:not(.sug){box-shadow:inset 3px 0 0 currentColor}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-e:not(.sug,.drag):hover,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-e:not(.sug,.drag):hover,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-e:not(.sug,.drag):hover{box-shadow:inset 3px 0 0 currentColor,inset 0 0 0 100vmax color-mix(in srgb,currentColor 9%,transparent)}}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-e.on:not(.sug,.drag),:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-e.on:not(.sug,.drag),:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-e.on:not(.sug,.drag){box-shadow:inset 3px 0 0 currentColor,inset 0 0 0 1px color-mix(in srgb,var(--dm-fg) 40%,transparent),inset 0 0 0 100vmax color-mix(in srgb,currentColor 11%,transparent)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-e.drag,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-e.drag,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-e.drag{box-shadow:inset 3px 0 0 currentColor,var(--dm-shadow-pop)}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-now,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-now,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-now{height:1px;margin-top:-.5px}
:root[data-style="clean"] .ecx:not(.crm-ecx) .ecx-now::before,:root [data-style="clean"] .ecx:not(.crm-ecx) .ecx-now::before,:root [data-style="clean"].ecx:not(.crm-ecx) .ecx-now::before{left:-3px;top:-3px;width:7px;height:7px}
:root[data-style="clean"] .ecx-pop:not(.crm-cpop),:root [data-style="clean"] .ecx-pop:not(.crm-cpop),:root [data-style="clean"].ecx-pop:not(.crm-cpop){padding:0 16px 16px;filter:none;transform:scale(.96);transform-origin:var(--dm-origin,top left);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t-fast)}
:root[data-style="clean"] .ecx-pop.open:not(.crm-cpop),:root [data-style="clean"] .ecx-pop.open:not(.crm-cpop),:root [data-style="clean"].ecx-pop.open:not(.crm-cpop){transform:none;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease)}
